using namespace std;

vector<string> chars(const string&s){

 vector<string> out;for(size_t i=0;i<s.size();){unsigned char b=s[i];

 size_t len=b<128?1:b<224?2:b<240?3:4;

 out.push_back(s.substr(i,len));i+=len;}return out;

}

int main(){
char c;cin.get(c);cout<<(int)(unsigned char)c<<'\n';
